"use client";

import { trpc } from "./Provider";

export default function Home() {
  const { data, isLoading, error } = trpc.hello.useQuery("tRPC v11");

  return (
    <div className="flex flex-1 items-center justify-center bg-zinc-50 font-sans dark:bg-black">
      <main className="flex w-full max-w-3xl flex-col items-center gap-6 rounded-2xl bg-white px-16 py-24 text-center shadow-sm dark:bg-black">
        <h1 className="text-3xl font-semibold leading-10 tracking-tight text-black dark:text-zinc-50">
          tRPC v11 + Next.js App Router
        </h1>
        <div id="result" className="text-lg text-zinc-600 dark:text-zinc-400">
          {isLoading && "Loading..."}
          {error && "Something went wrong."}
          {data && data}
        </div>
      </main>
    </div>
  );
}
